/// Get the bitmap for an ASCII character.
///
/// Returns None if the character is outside the supported range (0x20-0x7E).
/// Each byte in the returned array is one row (MSB is leftmost pixel).
#[inline]
pub fn glyph_bitmap(ch: u8) -> Option<&'static [u8; 16]> {
    if ch < FIRST_CP || ch > 0x7E {
        return None;
    }
    Some(&BITMAPS[(ch - FIRST_CP) as usize])
}

/// Measure text width in pixels (monospace: 8px per character).
#[inline]
pub fn measure_text_ascii(s: &str) -> (u32, u32) {
    let char_count = s.chars().take_while(|&c| c != '\n').count() as u32;
    (char_count * GLYPH_W, GLYPH_H)
}

/// Draw text using the built-in bitmap font.
///
/// Fast path for early boot when unifont cache isn't ready yet.
pub fn draw_builtin_text(
    painter: &mut dyn Painter,
    mut x: i32,
    y: i32,
    color: u32,
    text: &str,
) {
    let color_a = ((color >> 24) & 0xFF) as u8;
    let color_r = ((color >> 16) & 0xFF) as u8;
    let color_g = ((color >> 8) & 0xFF) as u8;
    let color_b = (color & 0xFF) as u8;

    for ch in text.bytes() {
        if ch == b'\n' {
            break;
        }

        let Some(bitmap) = glyph_bitmap(ch) else {
            // Skip unsupported characters, advance cursor
            x += GLYPH_W as i32;
            continue;
        };

        // Build pixel buffer for this glyph
        let mut pixels = [0u32; (GLYPH_W * GLYPH_H) as usize];
        for (row, &row_bits) in bitmap.iter().enumerate() {
            for bit in 0..8 {
                if (row_bits & (0x80 >> bit)) != 0 {
                    let idx = row * 8 + bit;
                    pixels[idx] = ((color_a as u32) << 24)
                        | ((color_r as u32) << 16)
                        | ((color_g as u32) << 8)
                        | (color_b as u32);
                }
            }
        }

        painter.blit_rgba_alpha(x, y, &pixels, GLYPH_W, GLYPH_H);
        x += GLYPH_W as i32;
    }
}

